1	import assert from "node:assert/strict";
2	import { createHash } from "node:crypto";
3	import http from "node:http";
4	import { mkdtemp, readFile, rm } from "node:fs/promises";
5	import { tmpdir } from "node:os";
6	import { join } from "node:path";
7	import type { AddressInfo } from "node:net";
8	import { test } from "node:test";
9	import { createApp } from "../src/server.js";
10	
11	async function withServer(
12	  fn: (baseUrl: string, dataDir: string) => Promise<void>,
13	): Promise<void> {
14	  const dataDir = await mkdtemp(join(tmpdir(), "syncbox-test-"));
15	  const server = createApp(dataDir).listen(0);
16	  try {
17	    const { port } = server.address() as AddressInfo;
18	    await fn(`http://127.0.0.1:${port}`, dataDir);
19	  } finally {
20	    server.close();
21	    await rm(dataDir, { recursive: true, force: true });
22	  }
23	}
24	
25	function request(
26	  url: string,
27	  options: http.RequestOptions,
28	  body?: Buffer,
29	): Promise<{ status: number; body: Buffer }> {
30	  return new Promise((resolve, reject) => {
31	    const req = http.request(url, options, (res) => {
32	      const chunks: Buffer[] = [];
33	      res.on("data", (chunk) => chunks.push(chunk));
34	      res.on("end", () =>
35	        resolve({
36	          status: res.statusCode ?? 0,
37	          body: Buffer.concat(chunks),
38	        }),
39	      );
40	    });
41	    req.on("error", reject);
42	    if (body) req.write(body);
43	    req.end();
44	  });
45	}
46	
47	/**
48	 * Like `request`, but sends `path` verbatim as the request-target instead of
49	 * going through `new URL(...)`, which normalizes literal ".." segments away
50	 * client-side (per the WHATWG URL spec) before the request ever hits the
51	 * wire. Traversal keys need to reach the server unmodified to exercise its
52	 * own defenses.
53	 */
54	function requestRawPath(
55	  baseUrl: string,
56	  path: string,
57	  method: string,
58	): Promise<{ status: number; body: Buffer }> {
59	  const { hostname, port } = new URL(baseUrl);
60	  return new Promise((resolve, reject) => {
61	    const req = http.request(
62	      { hostname, port, path, method, headers: { "content-length": "0" } },
63	      (res) => {
64	        const chunks: Buffer[] = [];
65	        res.on("data", (chunk) => chunks.push(chunk));
66	        res.on("end", () =>
67	          resolve({
68	            status: res.statusCode ?? 0,
69	            body: Buffer.concat(chunks),
70	          }),
71	        );
72	      },
73	    );
74	    req.on("error", reject);
75	    req.end();
76	  });
77	}
78	
79	test("GET /healthz returns 200", async () => {
80	  const server = createApp(await mkdtemp(join(tmpdir(), "syncbox-test-"))).listen(0);
81	  try {
82	    const { port } = server.address() as AddressInfo;
83	    const status = await new Promise<number | undefined>((resolve, reject) => {
84	      http
85	        .get(`http://127.0.0.1:${port}/healthz`, (res) => {
86	          res.resume();
87	          resolve(res.statusCode);
88	        })
89	        .on("error", reject);
90	    });
91	    assert.equal(status, 200);
92	  } finally {
93	    server.close();
94	  }
95	});
96	
97	test("PUT /blobs/{key} stores the blob and returns 201 with key/sha256/size", async () => {
98	  await withServer(async (baseUrl) => {
99	    const content = Buffer.from("hello syncbox");
100	    const res = await request(
101	      `${baseUrl}/blobs/greeting.txt`,
102	      { method: "PUT" },
103	      content,
104	    );
105	
106	    assert.equal(res.status, 201);
107	    const parsed = JSON.parse(res.body.toString("utf8"));
108	    assert.equal(parsed.key, "greeting.txt");
109	    assert.equal(parsed.size, content.length);
110	    assert.equal(
111	      parsed.sha256,
112	      createHash("sha256").update(content).digest("hex"),
113	    );
114	  });
115	});
116	
117	test("PUT /blobs/{key} writes the file to disk under the data dir", async () => {
118	  await withServer(async (baseUrl, dataDir) => {
119	    const content = Buffer.from("on disk");
120	    await request(`${baseUrl}/blobs/file.bin`, { method: "PUT" }, content);
121	
122	    const onDisk = await readFile(join(dataDir, "file.bin"));
123	    assert.deepEqual(onDisk, content);
124	  });
